#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define LRU_MAX_CAPACITY 8

typedef struct {
    int32_t capacity;
    int32_t count;
    int32_t mru;
    int32_t lru;
    int32_t key[LRU_MAX_CAPACITY];
    int32_t value[LRU_MAX_CAPACITY];
    int32_t prev[LRU_MAX_CAPACITY];
    int32_t next[LRU_MAX_CAPACITY];
} LruCache;

/* Provided by the candidate in solution.c */
void lru_init(LruCache *cache, int32_t capacity);
int32_t lru_get(LruCache *cache, int32_t key);
void lru_put(LruCache *cache, int32_t key, int32_t value);

int main(void)
{
    LruCache cache;
    memset(&cache, 0, sizeof cache);

    int capacity;
    if (scanf("%d", &capacity) != 1 || capacity < 1 || capacity > LRU_MAX_CAPACITY) {
        return 1;
    }
    lru_init(&cache, capacity);

    char op[8];
    while (scanf("%7s", op) == 1) {
        if (strcmp(op, "GET") == 0) {
            int key;
            if (scanf("%d", &key) != 1) {
                return 1;
            }
            int32_t value = lru_get(&cache, key);
            if (value < 0) {
                printf("MISS\n");
            } else {
                printf("%d\n", value);
            }
        } else if (strcmp(op, "PUT") == 0) {
            int key, value;
            if (scanf("%d %d", &key, &value) != 2) {
                return 1;
            }
            lru_put(&cache, key, value);
            printf("OK\n");
        } else {
            printf("UNKNOWN OP %s\n", op);
            return 1;
        }
    }
    return 0;
}

