"""Random GET/PUT sequences over a small key space, small enough capacities
that eviction happens often within a short sequence."""


def generate(rng, count):
    return [_sequence(rng, i + 1) for i in range(count)]


def _sequence(rng, index):
    capacity = rng.randint(2, 4)
    key_space = capacity + rng.randint(1, 3)
    n_ops = rng.randint(10, 18)

    lines = [str(capacity)]
    for _ in range(n_ops):
        key = rng.randrange(key_space)
        if rng.random() < 0.4:
            lines.append("GET %d" % key)
        else:
            value = rng.randrange(0, 500)
            lines.append("PUT %d %d" % (key, value))

    return {
        "name": "capacity %d, %d ops over %d keys #%d"
                % (capacity, n_ops, key_space, index),
        "stdin": "\n".join(lines) + "\n",
    }
